<script setup lang="ts">
import {
  Activity, Bell, Building2, CheckCircle2, CreditCard, KeyRound, LayoutDashboard,
  LifeBuoy, Menu, Search, ServerCog, Settings, ShieldCheck, Users, X,
} from '@lucide/vue'
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import api from '../api'
import PlatformSidebar from '../components/PlatformSidebar.vue'
import { useAuthStore } from '../stores/auth'
import { useLocaleStore } from '../stores/locale'

const auth=useAuthStore();const locale=useLocaleStore();const route=useRoute();const data=ref<any>(null);const loading=ref(true);const menu=ref(false);const search=ref('');const academyPage=ref(1);const userPage=ref(1);const userData=ref<any>({users:[],pagination:{page:1,last_page:1,total:0}});const plans=ref<any[]>([]);const editingUser=ref<any>(null);const userForm=ref({name:'',email:''});const userSaving=ref(false);const renewalOrganization=ref<any>(null);const renewing=ref(false);const renewForm=ref({plan_id:'',billing_cycle:'month',amount:'',note:'',is_gift:false})
const sections=['overview','academies','subscriptions','users','security','support','settings']
const section=computed(()=>sections.includes(String(route.params.section))?String(route.params.section):'overview')
const nav=[
  ['overview','Command centre',LayoutDashboard],['academies','Academies',Building2],['subscriptions','Subscriptions',CreditCard],
  ['users','Users & access',Users],['security','Security & audit',ShieldCheck],['settings/plans','Plans & payments',CreditCard],['support','Support operations',LifeBuoy],['settings','Platform settings',Settings],
]
const filteredOrganizations=computed(()=>{const value=search.value.trim().toLowerCase();if(!value)return data.value?.organizations||[];return (data.value?.organizations||[]).filter((item:any)=>[item.name_en,item.name_ar,item.email,item.city].some((field:any)=>String(field||'').toLowerCase().includes(value)))})
const title=computed(()=>locale.tr(String(nav.find(item=>item[0]===section.value)?.[1]||'Command centre')))
async function load(page=academyPage.value){loading.value=true;try{const tasks=[api.get('/platform/overview',{params:{search:section.value==='academies'?search.value||undefined:undefined,page:section.value==='academies'?page:1,per_page:25}})];if(section.value==='users')tasks.push(api.get('/platform/users',{params:{search:search.value||undefined,page:userPage.value,per_page:25}}));const responses=await Promise.all(tasks);data.value=responses[0].data;academyPage.value=data.value.organizations_pagination?.page||page;if(responses[1])userData.value=responses[1].data}finally{loading.value=false}}
function moveAcademyPage(page:number){const meta=data.value?.organizations_pagination;if(meta&&page>=1&&page<=meta.last_page&&!loading.value)load(page)}
function moveUserPage(page:number){const meta=userData.value.pagination;if(meta&&page>=1&&page<=meta.last_page&&!loading.value){userPage.value=page;load()}}
function editUser(user:any){editingUser.value=user;userForm.value={name:user.name,email:user.email}}
async function saveUser(){if(!editingUser.value||userSaving.value)return;if(!window.confirm(`Save account changes for ${editingUser.value.email}?`))return;userSaving.value=true;try{await api.patch(`/platform/users/${editingUser.value.id}`,userForm.value);editingUser.value=null;await load()}catch(e:any){window.alert(e.response?.data?.message||'Unable to update this account.')}finally{userSaving.value=false}}
async function deactivateUser(user:any){if(!window.confirm(`Deactivate ${user.name} (${user.email}) now? They will be signed out and blocked from further requests.`))return;try{await api.post(`/platform/users/${user.id}/deactivate`);await load()}catch(e:any){window.alert(e.response?.data?.message||'Unable to deactivate this account.')}}
async function openRenewal(organization:any){renewalOrganization.value=organization;renewForm.value={plan_id:'',billing_cycle:'month',amount:'',note:'',is_gift:false};if(!plans.value.length)plans.value=(await api.get('/platform/plans')).data.plans.filter((plan:any)=>plan.is_active&&plan.slug!=='free-trial');if(organization.current_subscription?.plan_id)renewForm.value.plan_id=String(organization.current_subscription.plan_id);else if(plans.value[0])renewForm.value.plan_id=String(plans.value[0].id);updateRenewAmount()}
function updateRenewAmount(){if(renewForm.value.is_gift){renewForm.value.amount='0';return}const plan=plans.value.find((item:any)=>String(item.id)===renewForm.value.plan_id);renewForm.value.amount=plan?String(((renewForm.value.billing_cycle==='year'?plan.yearly_price_minor:plan.monthly_price_minor)||0)/100):''}
function renewalOrganizationName(organization:any){return locale.locale==='ar'?(organization.name_ar||organization.name_en):(organization.name_en||organization.name_ar)}
async function renewSubscription(){if(!renewalOrganization.value||renewing.value)return;const plan=plans.value.find((item:any)=>String(item.id)===renewForm.value.plan_id);const amountMinor=Math.round(Number(renewForm.value.amount)*100);if(!plan||!Number.isFinite(amountMinor)||amountMinor<0||renewForm.value.note.trim().length<3||(renewForm.value.is_gift&&amountMinor!==0)||(!renewForm.value.is_gift&&amountMinor===0))return;const amountText=renewForm.value.is_gift?locale.tr('Gift renewal (no payment collected)'):(amountMinor/100).toFixed(2)+' '+(plan.currency||'EGP');if(!window.confirm(`${locale.tr('Confirm manual renewal for')} ${renewalOrganizationName(renewalOrganization.value)}?\n\n${locale.tr('Plan')}: ${plan.name}\n${locale.tr('Billing cycle')}: ${locale.tr(renewForm.value.billing_cycle==='year'?'Yearly':'Monthly')}\n${locale.tr('Amount')}: ${amountText}\n${locale.tr('Admin note')}: ${renewForm.value.note.trim()}`))return;renewing.value=true;try{await api.post(`/platform/organizations/${renewalOrganization.value.public_id}/renew`,{plan_id:plan.id,billing_cycle:renewForm.value.billing_cycle,amount_minor:amountMinor,note:renewForm.value.note.trim(),is_gift:renewForm.value.is_gift});renewalOrganization.value=null;await load()}catch(e:any){window.alert(e.response?.data?.message||locale.tr('Unable to renew this subscription.'))}finally{renewing.value=false}}
function initials(name:string){return name.split(' ').map(part=>part[0]).join('').slice(0,2).toUpperCase()}
onMounted(load)
watch(section,()=>{academyPage.value=1;load()});
let searchTimer: ReturnType<typeof setTimeout> | undefined
watch(search,()=>{if(!['academies','users'].includes(section.value))return; if(searchTimer)clearTimeout(searchTimer); searchTimer=setTimeout(()=>{academyPage.value=1;userPage.value=1;load()},300)})
</script>

<template><div class="app-shell platform-shell">
  <PlatformSidebar :open="menu" @close="menu=false"/>

  <main class="dashboard-main">
    <header><button class="mobile-nav" @click="menu=true"><Menu/></button><div class="global-search"><Search/><input v-model="search" :placeholder="locale.tr('Search academies, users or IDs…')"><kbd>{{locale.tr('GLOBAL')}}</kbd></div><div class="header-actions"><span class="platform-badge"><ShieldCheck/>{{locale.tr('SUPER ADMIN')}}</span><button><Bell/></button></div></header>
    <div v-if="loading" class="loading-state"><span></span>{{locale.tr('Loading platform operations…')}}</div>
    <div v-else class="dashboard-content platform-content">
      <div class="platform-page-head"><div><span>{{locale.tr('ACADEMYHUB CONTROL PLANE')}}</span><h1>{{title}}</h1><p>{{locale.tr('Global SaaS administration — separate from every academy and teaching workspace.')}}</p></div><div class="system-health"><i></i><span><small>{{locale.tr('SYSTEM STATUS')}}</small><b>{{locale.tr('All services operational')}}</b></span></div></div>

      <template v-if="section==='overview'">
        <section class="platform-stats"><article><span><Building2/></span><small>{{locale.tr('ORGANISATIONS')}}</small><b>{{data.stats.organizations}}</b><em>{{data.stats.trial_organizations}} currently trialling</em></article><article><span><Users/></span><small>{{locale.tr('PLATFORM USERS')}}</small><b>{{data.stats.users}}</b><em>Across {{data.stats.centres}} centres</em></article><article><span><CreditCard/></span><small>{{locale.tr('PAID SUBSCRIPTIONS')}}</small><b>{{data.stats.active_subscriptions}}</b><em>{{data.stats.trial_organizations}} conversion opportunities</em></article><article><span><ShieldCheck/></span><small>{{locale.tr('PLATFORM ADMINS')}}</small><b>{{data.stats.platform_admins}}</b><em>Global privileged accounts</em></article></section>
        <section class="platform-stats money-stats"><article><span><CreditCard/></span><small>COLLECTED ALL TIME</small><b>{{(data.stats.revenue_all_time_minor/100).toLocaleString()}} EGP</b><em>Recorded successful payments</em></article><article><span><Activity/></span><small>COLLECTED THIS MONTH</small><b>{{(data.stats.revenue_this_month_minor/100).toLocaleString()}} EGP</b><em>Paid payment records</em></article><article><span><CreditCard/></span><small>EXPECTED MONTHLY</small><b>{{(data.stats.expected_monthly_revenue_minor/100).toLocaleString()}} EGP</b><em>Active plan run rate</em></article><article><span><Activity/></span><small>EXPECTED YEARLY</small><b>{{(data.stats.expected_yearly_revenue_minor/100).toLocaleString()}} EGP</b><em>Annualized active subscriptions</em></article></section><section class="platform-grid finance-report-grid"><article class="platform-card"><div class="platform-card-head"><div><span>FINANCIAL REPORT</span><h2>Collected by month</h2><p>Successful subscription payments in the last 12 months.</p></div></div><div class="finance-months"><div v-for="month in data.financial_report.monthly_paid" :key="month.month"><span>{{month.month}}</span><i><b :style="{height:Math.max(3,month.paid_minor/Math.max(1,...data.financial_report.monthly_paid.map((item:any)=>item.paid_minor))*100)+'%'}"></b></i><strong>{{(month.paid_minor/100).toLocaleString()}}</strong></div></div></article><article class="platform-card"><div class="platform-card-head"><div><span>REVENUE BREAKDOWN</span><h2>Collected by plan</h2><p>Paid receipts grouped by subscription plan.</p></div></div><div class="finance-plan-list"><div v-for="item in data.financial_report.revenue_by_plan" :key="item.plan_name+item.currency"><b>{{item.plan_name}}</b><span>{{item.payments_count}} payments</span><strong>{{(item.amount_minor/100).toLocaleString()}} {{item.currency}}</strong></div><p v-if="!data.financial_report.revenue_by_plan.length">No completed subscription payments yet.</p></div></article></section><section class="platform-grid"><article class="platform-card tenant-card"><div class="platform-card-head"><div><span>{{locale.tr('RECENT TENANTS')}}</span><h2>{{locale.tr('Academy portfolio')}}</h2></div><RouterLink to="/admin/academies">{{locale.tr('View all')}} →</RouterLink></div><div class="admin-table"><div class="admin-table-row table-head"><span>{{locale.tr('Academy')}}</span><span>{{locale.tr('Plan status')}}</span><span>{{locale.tr('Centres')}}</span><span>{{locale.tr('People')}}</span></div><div v-for="organization in data.organizations.slice(0,5)" :key="organization.public_id" class="admin-table-row"><span class="tenant-name"><i>{{initials(organization.name_en||organization.name_ar)}}</i><b>{{locale.locale==='ar'?(organization.name_ar||organization.name_en):(organization.name_en||organization.name_ar)}}<small>{{organization.email||organization.public_id}}</small></b></span><span><em class="status-pill" :class="organization.subscription_status">{{organization.subscription_status}}</em></span><span>{{organization.branches_count}}</span><span>{{organization.users_count}}</span></div></div></article><article class="platform-card ops-card"><div class="platform-card-head"><div><span>{{locale.tr('OPERATIONAL WATCH')}}</span><h2>{{locale.tr('What needs attention')}}</h2></div><Activity/></div><ul><li><span class="watch-icon trial"><CreditCard/></span><div><b>{{data.stats.trial_organizations}} trial {{data.stats.trial_organizations===1?'academy':'academies'}}</b><p>Track conversion and expiry before access changes.</p></div></li><li><span class="watch-icon secure"><KeyRound/></span><div><b>{{data.stats.platform_admins}} privileged {{data.stats.platform_admins===1?'account':'accounts'}}</b><p>Keep global access intentionally small.</p></div></li><li><span class="watch-icon healthy"><CheckCircle2/></span><div><b>{{locale.tr('Tenant isolation healthy')}}</b><p>Organisation and centre middleware are enforced.</p></div></li></ul></article></section>
      </template>

      <template v-else-if="section==='academies'"><section class="platform-card full-card"><div class="platform-card-head"><div><span>TENANT DIRECTORY</span><h2>All academies</h2><p>Global visibility for support and subscription operations.</p></div><em>{{data.organizations_pagination.total}} results</em></div><div class="admin-table academy-directory"><div class="admin-table-row table-head"><span>Academy</span><span>Location</span><span>Subscription</span><span>Centres</span><span>Users</span><span>Created</span></div><div v-for="organization in filteredOrganizations" :key="organization.public_id" class="admin-table-row"><span class="tenant-name"><i>{{initials(organization.name_en||organization.name_ar)}}</i><b>{{organization.name_en||organization.name_ar}}<small>{{organization.email||organization.public_id}}</small></b></span><span>{{organization.city||'Not set'}}</span><span><em class="status-pill" :class="organization.subscription_status">{{organization.subscription_status}}</em></span><span>{{organization.branches_count}}</span><span>{{organization.users_count}}</span><span>{{organization.created_at}}</span></div></div><div class="admin-pagination"><button class="button secondary" :disabled="data.organizations_pagination.page<=1" @click="moveAcademyPage(data.organizations_pagination.page-1)">{{locale.tr('Previous')}}</button><span>{{data.organizations_pagination.page}} / {{data.organizations_pagination.last_page}} · {{data.organizations_pagination.total}} total</span><button class="button secondary" :disabled="data.organizations_pagination.page>=data.organizations_pagination.last_page" @click="moveAcademyPage(data.organizations_pagination.page+1)">{{locale.tr('Next')}}</button></div></section></template>

      <template v-else-if="section==='subscriptions'"><section class="platform-stats subscription-stats"><article><span><CreditCard/></span><small>ACTIVE</small><b>{{data.subscription_breakdown.active||0}}</b><em>Paying organisations</em></article><article><span><Activity/></span><small>TRIAL</small><b>{{data.subscription_breakdown.trial||0}}</b><em>In evaluation period</em></article><article><span><ShieldCheck/></span><small>TOTAL TENANTS</small><b>{{data.stats.organizations}}</b><em>All subscription states</em></article></section><section class="platform-card full-card"><div class="platform-card-head"><div><span>SUBSCRIPTION OPERATIONS</span><h2>Plans and lifecycle</h2><p>Renew, review, and record manual payment notes for each academy.</p></div></div><div class="admin-table subscription-directory"><div class="admin-table-row table-head"><span>Academy</span><span>Status / plan</span><span>Expires</span><span>Centres</span><span>Action</span></div><div v-for="organization in data.organizations" :key="organization.public_id" class="admin-table-row"><span class="tenant-name"><i>{{initials(organization.name_en||organization.name_ar)}}</i><b>{{organization.name_en||organization.name_ar}}<small>{{organization.email||organization.public_id}}</small></b></span><span><em class="status-pill" :class="organization.subscription_status">{{organization.subscription_status}}</em><small class="admin-subdetail">{{organization.current_subscription?.plan_name||'No current plan'}}</small></span><span>{{organization.current_subscription?.ends_at||organization.trial_ends_at||'—'}}</span><span>{{organization.branches_count}}</span><span><button class="button secondary admin-action" @click="openRenewal(organization)">Renew manually</button></span></div></div><div class="admin-pagination"><button class="button secondary" :disabled="(data.organizations_pagination?.page||1)<=1" @click="moveAcademyPage(data.organizations_pagination.page-1)">Previous</button><span>{{data.organizations_pagination?.page||1}} / {{data.organizations_pagination?.last_page||1}}</span><button class="button secondary" :disabled="(data.organizations_pagination?.page||1)>=(data.organizations_pagination?.last_page||1)" @click="moveAcademyPage(data.organizations_pagination.page+1)">Next</button></div></section></template>

      <template v-else-if="section==='users'"><section class="platform-card full-card"><div class="platform-card-head"><div><span>IDENTITY DIRECTORY</span><h2>All platform users</h2><p>Edit account details or immediately deactivate access.</p></div><em>{{userData.pagination.total}} total</em></div><div class="admin-table user-directory"><div class="admin-table-row table-head"><span>User</span><span>Identity status</span><span>Access level</span><span>Joined</span><span>Actions</span></div><div v-for="user in userData.users" :key="user.id" class="admin-table-row"><span class="tenant-name"><i>{{initials(user.name)}}</i><b>{{user.name}}<small>{{user.email}} · {{user.organizations.map((org:any)=>org.name_en||org.name_ar).join(', ')||'No academy membership'}}</small></b></span><span><em class="status-pill" :class="!user.is_active?'expired':user.verified?'active':'pending'">{{!user.is_active?'Deactivated':user.verified?'Verified':'Unverified'}}</em></span><span>{{user.is_platform_admin?'Platform administrator':'Tenant user'}}</span><span>{{user.created_at}}</span><span class="admin-user-actions"><template v-if="user.is_platform_admin"><span class="protected-account">{{locale.tr('Protected account')}}</span></template><template v-else><button class="button secondary admin-action" @click="editUser(user)">Edit</button><button class="button danger admin-action" :disabled="!user.is_active" @click="deactivateUser(user)">Deactivate</button></template></span></div></div><div class="admin-pagination"><button class="button secondary" :disabled="userData.pagination.page<=1" @click="moveUserPage(userData.pagination.page-1)">Previous</button><span>{{userData.pagination.page}} / {{userData.pagination.last_page}}</span><button class="button secondary" :disabled="userData.pagination.page>=userData.pagination.last_page" @click="moveUserPage(userData.pagination.page+1)">Next</button></div></section></template>

      <template v-else-if="section==='security'"><section class="platform-grid"><article class="platform-card security-summary"><div class="platform-card-head"><div><span>PRIVILEGED ACCESS</span><h2>Security posture</h2></div><ShieldCheck/></div><div class="security-score"><strong>A</strong><div><b>Core controls enabled</b><p>Email verification, signed recovery, CSRF rotation and tenant boundaries are active.</p></div></div><ul><li><CheckCircle2/>Verified identity required before tenant access</li><li><CheckCircle2/>Global routes restricted to platform admins</li><li><CheckCircle2/>Organisation and centre context resolved server-side</li></ul></article><article class="platform-card"><div class="platform-card-head"><div><span>RECENT AUDIT EVENTS</span><h2>Platform activity</h2></div><Activity/></div><div class="audit-list"><div v-for="event in data.recent_activity" :key="event.id"><span></span><b>{{event.event}}</b><small>{{event.created_at}}</small></div><p v-if="!data.recent_activity.length">No audit events recorded yet.</p></div></article></section></template>

      <template v-else-if="section==='support'"><section class="empty-admin-state"><span><LifeBuoy/></span><small>SUPPORT OPERATIONS</small><h2>A clean place for tenant support.</h2><p>Academy lookup is already available from the global search. Ticket queues, impersonation approvals and service notices will live here without exposing classroom tools.</p><div><b>0</b><span>Open support cases</span></div></section></template>

      <template v-else><section class="settings-grid"><article><span><ServerCog/></span><small>PLATFORM IDENTITY</small><h2>AcademyHub SaaS</h2><p>Global product name, sender identity and public URLs.</p><button disabled>Configuration coming next</button></article><article><span><KeyRound/></span><small>AUTHENTICATION</small><h2>Secure by default</h2><p>Verified email and protected password recovery are enabled.</p><em>Enabled</em></article><article><span><Bell/></span><small>OUTBOUND EMAIL</small><h2>Development mail</h2><p>Messages currently use the Laravel log transport until production SMTP is configured.</p><em class="warning">Needs SMTP</em></article></section></template>
    </div>
  </main>
<div v-if="editingUser" class="modal-backdrop" @click.self="editingUser=null"><section class="centre-modal platform-admin-modal"><button class="modal-close" @click="editingUser=null"><X/></button><h2>Edit user account</h2><p>Changing the email address will require the user to verify it again.</p><form @submit.prevent="saveUser"><label>Name<input v-model="userForm.name" required maxlength="120"></label><label>Email<input v-model="userForm.email" type="email" required maxlength="190"></label><div class="modal-actions"><button type="button" class="button secondary" @click="editingUser=null">Cancel</button><button class="button primary" :disabled="userSaving">Save changes</button></div></form></section></div><div v-if="renewalOrganization" class="modal-backdrop" @click.self="renewalOrganization=null"><section class="centre-modal platform-admin-modal renewal-modal" data-no-dom-translate :lang="locale.locale" :dir="locale.locale==='ar'?'rtl':'ltr'"><button class="modal-close" @click="renewalOrganization=null"><X/></button><h2>{{locale.tr('Manual subscription renewal')}}</h2><p>{{locale.tr('Renew subscription for')}} {{renewalOrganizationName(renewalOrganization)}}. {{locale.tr('The payment and administrator note are retained in the audit record.')}}</p><form @submit.prevent="renewSubscription"><label>{{locale.tr('Plan')}}<select v-model="renewForm.plan_id" required @change="updateRenewAmount"><option v-for="plan in plans" :key="plan.id" :value="String(plan.id)">{{plan.name}}</option></select></label><label>{{locale.tr('Billing cycle')}}<select v-model="renewForm.billing_cycle" required @change="updateRenewAmount"><option value="month">{{locale.tr('Monthly')}}</option><option value="year">{{locale.tr('Yearly')}}</option></select></label><label class="renew-gift-toggle"><input v-model="renewForm.is_gift" type="checkbox" @change="updateRenewAmount"><span>{{locale.tr('Give this renewal for free (gift)')}}</span></label><label>{{renewForm.is_gift?locale.tr('Amount (gift renewal)'):locale.tr('Amount paid (EGP)')}}<input v-model="renewForm.amount" type="number" min="0" step="0.01" required :disabled="renewForm.is_gift"></label><p v-if="renewForm.is_gift" class="renew-gift-note">{{locale.tr('No payment will be collected. The subscription is recorded as a gift, not revenue.')}}</p><label>{{locale.tr('Admin note')}}<textarea v-model="renewForm.note" rows="4" minlength="3" maxlength="2000" required :placeholder="locale.tr('Explain the reason for this renewal or gift')"></textarea></label><div class="modal-actions"><button type="button" class="button secondary" @click="renewalOrganization=null">{{locale.tr('Cancel')}}</button><button class="button primary" :disabled="renewing">{{renewing?locale.tr('Savingâ€¦'):locale.tr('Confirm renewal')}}</button></div></form></section></div></div></template>
